DELETE FROM cards;

INSERT INTO cards (id, name, meaning, diet, era, image_url, height, weight, intelligence, speed, strength, description) VALUES
-- Carnivores
('a1000000-0000-0000-0000-000000000001', 'Tyrannosaurus Rex', 'Tyrant Lizard King', 'Carnivore', 'Late Cretaceous', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020844/dino-top-trumps/tyrannosaurus-rex.jpg', 85, 95, 55, 50, 98, 'More opportunist than apex hunter. Relied on devastating ambushes or bullying smaller predators off their kills, with exceptional vision and a surprisingly dedicated parenting instinct.'),
('a1000000-0000-0000-0000-000000000002', 'Velociraptor', 'Swift Thief', 'Carnivore', 'Late Cretaceous', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020846/dino-top-trumps/velociraptor.jpg', 20, 10, 92, 95, 35, 'Pack hunters that developed primitive vocal communication. Relied on razor-sharp talons over teeth, leaping onto prey and scaling cliffs to nest on ledges larger predators could never reach.'),
('a1000000-0000-0000-0000-000000000003', 'Spinosaurus', 'Spine Lizard', 'Carnivore', 'Late Cretaceous', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020847/dino-top-trumps/spinosaurus.jpg', 90, 90, 60, 40, 88, 'The largest land predator to ever exist. Semi-aquatic and cunning — would catch small fish and release them as live bait to lure sharks and larger prey.'),
('a1000000-0000-0000-0000-000000000004', 'Allosaurus', 'Different Lizard', 'Carnivore', 'Late Jurassic', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020848/dino-top-trumps/allosaurus.jpg', 70, 75, 50, 55, 82, 'Apex predator of the Late Jurassic, with claws as lethal as its jaws. Could pounce and pin prey under its weight, fearing only its own kind and the toughest armoured herbivores.'),
('a1000000-0000-0000-0000-000000000005', 'Giganotosaurus', 'Giant Southern Lizard', 'Carnivore', 'Late Cretaceous', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020850/dino-top-trumps/giganotosaurus.jpg', 88, 88, 48, 45, 95, 'Built for pursuit over ambush, with a long skull designed for slashing bites that weakened prey over time rather than delivering a single killing blow.'),
('a1000000-0000-0000-0000-000000000006', 'Dilophosaurus', 'Two-Crested Lizard', 'Carnivore', 'Early Jurassic', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020851/dino-top-trumps/dilophosaurus.jpg', 45, 30, 55, 65, 50, 'A specialist nighttime hunter, stalking through bioluminescent swamps. Its twin crests broke up its silhouette to mimic the glowing flora — invisible until the final moment.'),
('a1000000-0000-0000-0000-000000000007', 'Carnotaurus', 'Meat-Eating Bull', 'Carnivore', 'Late Cretaceous', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020852/dino-top-trumps/carnotaurus.jpg', 55, 60, 40, 70, 72, 'One of the fastest large predators ever. Its compact skull and forward-facing horns suggest a charging style — slamming into prey at full speed before the killing bite.'),
('a1000000-0000-0000-0000-000000000008', 'Baryonyx', 'Heavy Claw', 'Carnivore', 'Early Cretaceous', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020854/dino-top-trumps/baryonyx.jpg', 50, 55, 58, 50, 65, 'A specialist fish-hunter with enormous hooked claws for snatching prey from the water. Its crocodile-like snout made it perfectly adapted for riverside ambushes.'),
('a1000000-0000-0000-0000-000000000009', 'Deinonychus', 'Terrible Claw', 'Carnivore', 'Early Cretaceous', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020855/dino-top-trumps/deinonychus.jpg', 25, 15, 88, 85, 45, 'The dinosaur that proved some species were fast, warm-blooded, and intelligent. Hunted in coordinated packs using its sickle claw to pin prey much larger than itself.'),
('a1000000-0000-0000-0000-000000000010', 'Megalosaurus', 'Great Lizard', 'Carnivore', 'Middle Jurassic', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020856/dino-top-trumps/megalosaurus.jpg', 55, 50, 45, 50, 70, 'The first dinosaur ever scientifically described, discovered in 1824. What it lacked in specialisation it made up for in raw versatility — equally capable of hunting and scavenging.'),
('a1000000-0000-0000-0000-000000000011', 'Compsognathus', 'Elegant Jaw', 'Carnivore', 'Late Jurassic', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020858/dino-top-trumps/compsognathus.jpg', 5, 2, 65, 90, 8, 'The vermin of the dinosaur world. Tiny pack scavengers that appeared when the coast was clear, picking over kills left by larger predators before vanishing into undergrowth.'),
('a1000000-0000-0000-0000-000000000012', 'Ceratosaurus', 'Horned Lizard', 'Carnivore', 'Late Jurassic', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020859/dino-top-trumps/ceratosaurus.jpg', 50, 45, 42, 55, 68, 'Evolved to eat carrion that would poison other dinosaurs. The bacteria in its gut meant even a non-fatal bite could kill over time — like a prehistoric Komodo dragon.'),

-- Herbivores
('a1000000-0000-0000-0000-000000000013', 'Triceratops', 'Three-Horned Face', 'Herbivore', 'Late Cretaceous', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020860/dino-top-trumps/triceratops.jpg', 55, 85, 35, 30, 88, 'Its three horns were not just for display — fossils show healed puncture wounds from horn-to-horn combat. One of the few herbivores that could face a T-Rex and survive.'),
('a1000000-0000-0000-0000-000000000014', 'Stegosaurus', 'Roof Lizard', 'Herbivore', 'Late Jurassic', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020862/dino-top-trumps/stegosaurus.jpg', 55, 70, 12, 25, 75, 'Its bony plates likely regulated temperature and flushed with colour to intimidate rivals. Its spiked tail — the "thagomizer" — could pierce predator bone.'),
('a1000000-0000-0000-0000-000000000015', 'Brachiosaurus', 'Arm Lizard', 'Herbivore', 'Late Jurassic', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020863/dino-top-trumps/brachiosaurus.jpg', 98, 98, 25, 15, 60, 'One of the tallest creatures to ever live. Its sheer size was its defence — a healthy adult had virtually no natural predators. Consumed over 400kg of vegetation daily.'),
('a1000000-0000-0000-0000-000000000016', 'Ankylosaurus', 'Fused Lizard', 'Herbivore', 'Late Cretaceous', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020865/dino-top-trumps/ankylosaurus.jpg', 35, 65, 30, 20, 85, 'A living fortress with fused bony plates and a tail club that could shatter bone. Even a T-Rex would think twice. Its only vulnerability — an unarmoured belly.'),
('a1000000-0000-0000-0000-000000000017', 'Diplodocus', 'Double Beam', 'Herbivore', 'Late Jurassic', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020866/dino-top-trumps/diplodocus.jpg', 92, 80, 20, 18, 45, 'One of the longest dinosaurs ever, using its whip-like tail for defence and communication. Relied on herd behaviour and sheer mass rather than intelligence for survival.'),
('a1000000-0000-0000-0000-000000000018', 'Parasaurolophus', 'Near Crested Lizard', 'Herbivore', 'Late Cretaceous', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020868/dino-top-trumps/parasaurolophus.jpg', 60, 55, 50, 45, 35, 'Its hollow crest produced deep trumpeting calls that carried for kilometres, coordinating herd movement and warning of predators — an early long-range communication system.'),
('a1000000-0000-0000-0000-000000000019', 'Iguanodon', 'Iguana Tooth', 'Herbivore', 'Early Cretaceous', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020869/dino-top-trumps/iguanodon.jpg', 55, 60, 45, 35, 50, 'One of the first dinosaurs ever discovered. Could walk on two or four legs, and its distinctive thumb spike served for both defence and foraging. A true generalist.'),
('a1000000-0000-0000-0000-000000000020', 'Pachycephalosaurus', 'Thick-Headed Lizard', 'Herbivore', 'Late Cretaceous', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020870/dino-top-trumps/pachycephalosaurus.jpg', 40, 40, 35, 45, 70, 'The headbutter. Its skull — up to 25cm thick — was used in head-to-head combat for mates and territory, or as a battering ram against predators.'),
('a1000000-0000-0000-0000-000000000021', 'Apatosaurus', 'Deceptive Lizard', 'Herbivore', 'Late Jurassic', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020872/dino-top-trumps/apatosaurus.jpg', 88, 90, 18, 15, 55, 'Travelled in vast herds that reshaped landscapes, trampling forests and creating migration trails that lasted generations. Its footsteps shook the earth.'),
('a1000000-0000-0000-0000-000000000022', 'Protoceratops', 'First Horned Face', 'Herbivore', 'Late Cretaceous', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020873/dino-top-trumps/protoceratops.jpg', 25, 20, 38, 40, 30, 'Small but fierce. Famous for a fossil preserved locked in combat with a Velociraptor — proof that even small herbivores fought to the death when cornered.'),
('a1000000-0000-0000-0000-000000000023', 'Styracosaurus', 'Spiked Lizard', 'Herbivore', 'Late Cretaceous', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020875/dino-top-trumps/styracosaurus.jpg', 40, 50, 32, 30, 72, 'Its elaborate frill of long horns was built for intimidation as much as defence. The more spectacular the display, the more dominant the individual.'),
('a1000000-0000-0000-0000-000000000024', 'Tenontosaurus', 'Sinew Lizard', 'Herbivore', 'Early Cretaceous', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020876/dino-top-trumps/tenontosaurus.jpg', 45, 55, 28, 35, 45, 'A frequent target of Deinonychus packs. Fossil sites show multiple raptors alongside a single Tenontosaurus — evidence of coordinated pack hunts. The prey that made predators evolve.'),

-- Omnivores
('a1000000-0000-0000-0000-000000000025', 'Gallimimus', 'Chicken Mimic', 'Omnivore', 'Late Cretaceous', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020877/dino-top-trumps/gallimimus.jpg', 35, 25, 62, 92, 22, 'Built for speed above all else. Travelled in large flocks across open plains, relying on collective vigilance and explosive acceleration to escape. Could outrun almost anything.'),
('a1000000-0000-0000-0000-000000000026', 'Oviraptor', 'Egg Thief', 'Omnivore', 'Late Cretaceous', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020879/dino-top-trumps/oviraptor.jpg', 22, 18, 72, 70, 25, 'Long misnamed "Egg Thief" — it was actually found protecting its own nest. A devoted parent with a strong beak for crushing shellfish and hard fruit.'),
('a1000000-0000-0000-0000-000000000027', 'Ornithomimus', 'Bird Mimic', 'Omnivore', 'Late Cretaceous', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020880/dino-top-trumps/ornithomimus.jpg', 30, 22, 60, 88, 20, 'The ultimate survivor. Fast, adaptable, and omnivorous — its beak could handle seeds, insects, and small animals equally well. Thrived where specialists struggled.'),
('a1000000-0000-0000-0000-000000000028', 'Therizinosaurus', 'Scythe Lizard', 'Omnivore', 'Late Cretaceous', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020882/dino-top-trumps/therizinosaurus.jpg', 72, 70, 35, 25, 78, 'Possessed the longest claws of any known animal at 70cm each. Primarily herbivorous, using scythe-like claws to pull down branches — and to devastate any predator foolish enough to attack.'),
('a1000000-0000-0000-0000-000000000029', 'Beipiaosaurus', 'Beipiao Lizard', 'Omnivore', 'Early Cretaceous', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020883/dino-top-trumps/beipiaosaurus.jpg', 30, 25, 78, 58, 28, 'A cunning opportunist with a symbiotic edge. Would snatch eggs and lure larger animals to the water''s edge — where something far more dangerous waited beneath the surface.'),

-- Flying / Marine
('a1000000-0000-0000-0000-000000000030', 'Pteranodon', 'Toothless Wing', 'Carnivore', 'Late Cretaceous', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020884/dino-top-trumps/pteranodon.jpg', 30, 15, 58, 80, 18, 'A flying reptile with a 7-metre wingspan that soared over oceans scooping fish from the surface, rarely needing to flap. Its head crest aided steering and attracted mates.'),
('a1000000-0000-0000-0000-000000000031', 'Pterodactyl', 'Wing Finger', 'Carnivore', 'Late Jurassic', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020886/dino-top-trumps/pterodactyl.jpg', 15, 8, 52, 85, 12, 'The first pterosaur ever discovered. Smaller and more agile than Pteranodon, it hunted close to shore and launched from the ground with a powerful four-limbed leap.'),
('a1000000-0000-0000-0000-000000000032', 'Archaeopteryx', 'Ancient Wing', 'Carnivore', 'Late Jurassic', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020887/dino-top-trumps/archaeopteryx.jpg', 8, 3, 55, 72, 5, 'The missing link between dinosaurs and birds. Feathered but clawed, it could glide but not truly fly — a glimpse into the moment dinosaurs took to the skies.'),
('a1000000-0000-0000-0000-000000000033', 'Mosasaurus', 'Meuse River Lizard', 'Carnivore', 'Late Cretaceous', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020889/dino-top-trumps/mosasaurus.jpg', 80, 92, 52, 60, 90, 'Undisputed apex predator of the ancient oceans. A double-hinged jaw that could swallow prey whole. Nothing was safe — including sharks and other mosasaurs.'),
('a1000000-0000-0000-0000-000000000034', 'Plesiosaurus', 'Near Lizard', 'Carnivore', 'Early Jurassic', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020890/dino-top-trumps/plesiosaurus.jpg', 60, 45, 48, 55, 55, 'A graceful marine predator with a serpentine neck that struck at fish with lightning speed. The inspiration behind sea monster legends, including the Loch Ness Monster.'),

-- Special
('a1000000-0000-0000-0000-000000000035', 'Deinosuchus', 'Terrible Crocodile', 'Carnivore', 'Late Cretaceous', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020891/dino-top-trumps/deinosuchus.jpg', 25, 85, 30, 15, 92, 'A 10-metre ambush predator capable of dragging even the largest dinosaurs underwater. Its only real threat was its own kind — populations controlled by territorial combat between rivals.'),
('a1000000-0000-0000-0000-000000000036', 'Troodon', 'Wounding Tooth', 'Carnivore', 'Late Cretaceous', 'https://res.cloudinary.com/djnj9zlw3/image/upload/v1774020893/dino-top-trumps/troodon.jpg', 18, 12, 98, 75, 22, 'Pound for pound, the most intelligent dinosaur ever. Small pack hunters that attacked from multiple angles, darting through undergrowth using high-pitched screams to communicate and disorient prey.');
